import React, { useEffect, useState } from 'react';
import { SafeAreaView, Text, StyleSheet, Button, View } from 'react-native';
import ProductList from '../components/ProductList';

export default function HomeScreen({ navigation }) {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3000/api/products')
      .then(res => res.json())
      .then(data => setProducts(data))
      .catch(() => setProducts([]));
  }, []);

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.brand}>Gearspot</Text>
        <Text style={styles.subtitle}>Vuokraa suppareita, sähköpyöriä ja varusteita järvien läheltä.</Text>
      </View>
      <Button title="Etsi tuotetta järven läheltä" onPress={() => navigation.navigate('MapSearch')} />
      <Text style={styles.title}>Vuokrattavat tuotteet</Text>
      <ProductList products={products} navigation={navigation} />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  header: { marginBottom: 16 },
  brand: { fontSize: 26, fontWeight: '800', marginBottom: 4 },
  subtitle: { color: '#555' },
  title: { fontSize: 20, fontWeight: '600', marginVertical: 16 }
});
